window.VO = [{"id":"a1","scene":"night","text":"Two thirteen in the morning. Another domain ticket.","t0":1.5,"t1":5.4603,"beat0":2,"beat1":7.28},{"id":"a2","scene":"night","text":"Maya. She added her records three days ago, and she launches tomorrow.","t0":6.375,"t1":11.5183,"beat0":8.5,"beat1":15.358},{"id":"b1","scene":"night","text":"She typed her whole domain into the name field. Of course she did. Nobody ever tells you how this works.","t0":12.1875,"t1":20.5919,"beat0":16.25,"beat1":27.456},{"id":"b2","scene":"night","text":"Every week, the same questions. Where are my DNS settings? Which records? Why does it still say pending?","t0":21.1875,"t1":29.649,"beat0":28.25,"beat1":39.532},{"id":"b3","scene":"night","text":"None of it is about our product. All of it lands on us.","t0":30.375,"t1":34.4952,"beat0":40.5,"beat1":45.994},{"id":"c1","scene":"turn","text":"So we shipped Custom Domain.","t0":36,"t1":37.6298,"beat0":48,"beat1":50.173},{"id":"d1","scene":"morning","text":"Now, customers like Maya sign in to their DNS provider, right inside our app, and approve.","t0":39,"t1":46.3783,"beat0":52,"beat1":61.838},{"id":"d2","scene":"morning","text":"The records are written for them, checked, and kept that way.","t0":46.875,"t1":50.8218,"beat0":62.5,"beat1":67.762},{"id":"d3","scene":"morning","text":"Her next domain went live while she was still on the page.","t0":51.5625,"t1":55.3459,"beat0":68.75,"beat1":73.794},{"id":"e1","scene":"morning","text":"And at two thirteen in the morning, I'm asleep.","t0":56.4375,"t1":59.6769,"beat0":75.25,"beat1":79.569},{"id":"f1","scene":"end","text":"Custom Domain. You never touch their DNS. Neither does your support team.","t0":60.9375,"t1":66.8831,"beat0":81.25,"beat1":89.177}];
